insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  've-004',
  'vertraege',
  'vt-arten',
  'multiple',
  null,
  'Was sollte ein IT-Dienstleistungsvertrag mindestens regeln?',
  'Mindestinhalte: Vertragsparteien, Leistungsbeschreibung, Vergütung, Termine, Mitwirkungspflichten des Auftraggebers, Abnahme, Gewährleistung, Haftung, Datenschutz/Geheimhaltung, Laufzeit und Kündigung.
Die Mitwirkungspflichten werden am häufigsten vergessen und führen am häufigsten zu Streit: Wenn der Auftraggeber Testdaten oder Ansprechpartner nicht liefert, kann der Auftragnehmer den Termin nicht halten - ohne Regelung steht dann Aussage gegen Aussage.',
  1,
  ARRAY['vertragsbestandteile']::text[],
  null,
  '{"choices":[{"text":"Leistungsbeschreibung bzw. Verweis auf das Pflichtenheft","is_correct":true,"rationale":"Ohne beschriebene Leistung lässt sich später nicht feststellen, ob erfüllt wurde."},{"text":"Vergütung und Zahlungsbedingungen","is_correct":true,"rationale":"Höhe, Fälligkeit und Zahlungsziel gehören zwingend hinein."},{"text":"Termine und Fristen","is_correct":true,"rationale":"Feste Termine machen Verzug eindeutig feststellbar - bei einem Kalendertermin sogar ohne Mahnung."},{"text":"Regelungen zu Gewährleistung und Haftung","is_correct":true,"rationale":"Legt fest, wer bei Mängeln und Schäden in welchem Umfang einsteht."},{"text":"Die Namen aller eingesetzten Entwickler","is_correct":false,"rationale":"Falsch. Das wäre unpraktikabel - Personal wechselt. Geregelt werden höchstens Qualifikationsanforderungen."},{"text":"Vereinbarungen zu Datenschutz und Vertraulichkeit","is_correct":true,"rationale":"Verarbeitet der Dienstleister personenbezogene Daten im Auftrag, ist ein Auftragsverarbeitungsvertrag sogar Pflicht (Art. 28 DSGVO)."}]}'::jsonb,
