values (
  'a7-vz-4',
  'vertraege',
  'vt-zustandekommen',
  'single',
  'Ein Onlineshop zeigt ein Notebook wegen eines Eingabefehlers für 89 € statt 899 €. Ein Kunde bestellt sofort. Er erhält eine automatische E-Mail: „Vielen Dank, wir haben Ihre Bestellung erhalten.“',
  'Ist damit ein Kaufvertrag zustande gekommen?',
  'Artikelseite = Aufforderung zum Antrag, Bestellung = Antrag, Eingangsbestätigung = nur Zugangsbestätigung (§ 312i BGB). Erst eine Auftrags- oder Versandbestätigung wäre die Annahme. Hätte der Shop angenommen, könnte er wegen des Eingabefehlers (Erklärungsirrtum) unverzüglich anfechten.',
  2,
  '{}',
  null,
  '{"choices":[{"text":"Nein. Die Artikelseite ist nur eine Aufforderung zum Antrag, und die Eingangsbestätigung ist noch keine Annahme.","is_correct":true,"rationale":"Der Kunde hat den Antrag gemacht. Die E-Mail bestätigt nur den Zugang der Bestellung, eine Annahme steht noch aus."},{"text":"Ja, weil der im Shop angezeigte Preis verbindlich ist.","is_correct":false,"rationale":"Webshop-Seiten richten sich an alle und sind keine Anträge – der Shop muss nicht zu jedem angezeigten Preis verkaufen."},{"text":"Ja, weil jede Bestätigungs-E-Mail eine Annahme ist.","is_correct":false,"rationale":"Entscheidend ist der Wortlaut: „Bestellung erhalten“ bestätigt nur den Eingang, „Wir nehmen an“ wäre eine Annahme."},{"text":"Nein, weil Verträge im Internet schriftlich geschlossen werden müssen.","is_correct":false,"rationale":"Kaufverträge sind formfrei, auch im Internet genügt ein Klick."}]}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
  kind = excluded.kind,
  scenario = excluded.scenario,
  prompt = excluded.prompt,
  explanation = excluded.explanation,
  difficulty = excluded.difficulty,
  tags = excluded.tags,
  data = excluded.data,
  catalog_status = excluded.catalog_status,
  is_active = true;

insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'a7-vz-5',
  'vertraege',
  'vt-zustandekommen',
  'matching',
  null,
  'Ist das Rechtsgeschäft nichtig, anfechtbar oder wirksam?',
  'Nichtig: Geschäftsunfähigkeit, fehlende Form, Schein- und Scherzgeschäft, Gesetzes- oder Sittenverstoß. Anfechtbar: Erklärungs-, Inhalts- und Eigenschaftsirrtum, Täuschung, Drohung. Wer sich nur über seine Beweggründe irrt, bleibt an den Vertrag gebunden.',
  2,
  '{}',
  null,
  '{"buckets":["nichtig","anfechtbar","wirksam"],"match_items":[{"text":"Ein 6-jähriges Kind kauft ein Videospiel für 60 €.","bucket":0,"rationale":"Unter 7 Jahren geschäftsunfähig – die Erklärung ist nichtig (§ 105 BGB)."},{"text":"Zwei Personen verkaufen ein Grundstück per Handschlag, ohne Notar.","bucket":0,"rationale":"Die gesetzlich vorgeschriebene notarielle Form fehlt (§ 125 BGB)."},{"text":"Ein Händler tippt im Angebot 1.000 statt 100 Stück.","bucket":1,"rationale":"Erklärungsirrtum nach § 119 Abs. 1 BGB – unverzüglich anfechtbar."},{"text":"Ein Verkäufer verschweigt bewusst einen reparierten Wasserschaden am Server.","bucket":1,"rationale":"Arglistige Täuschung nach § 123 BGB – anfechtbar innerhalb eines Jahres ab Entdeckung."},{"text":"Ein Kunde kauft Monitore und stellt später fest, dass er sie gar nicht braucht.","bucket":2,"rationale":"Motivirrtum – kein Anfechtungsgrund, der Vertrag bleibt wirksam."},{"text":"Ein Systemhaus hat intern falsch kalkuliert und merkt, dass der vereinbarte Preis zu niedrig ist.","bucket":2,"rationale":"Ein interner Kalkulationsirrtum ist ein Motivirrtum und berechtigt nicht zur Anfechtung."}]}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
  kind = excluded.kind,
  scenario = excluded.scenario,
  prompt = excluded.prompt,
  explanation = excluded.explanation,
  difficulty = excluded.difficulty,
  tags = excluded.tags,
  data = excluded.data,
  catalog_status = excluded.catalog_status,
  is_active = true;

insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'a7-vz-6',
  'vertraege',
  'vt-zustandekommen',
  'multiple',
  null,
  'Welche Aussagen zu Allgemeinen Geschäftsbedingungen (AGB) sind richtig?',
  'AGB sind vorformulierte Bedingungen für viele Verträge. Sie werden nur einbezogen, wenn darauf hingewiesen wurde, und unterliegen einer Inhaltskontrolle: Individualabreden gehen vor, überraschende und unangemessene Klauseln sind unwirksam, der Rest des Vertrags bleibt bestehen.',
  2,
  '{}',
  null,
  '{"choices":[{"text":"Individuell ausgehandelte Absprachen haben Vorrang vor AGB.","is_correct":true,"rationale":"So steht es in § 305b BGB."},{"text":"Überraschende Klauseln, mit denen der Kunde nicht rechnen musste, werden nicht Vertragsbestandteil.","is_correct":true,"rationale":"§ 305c BGB schützt vor versteckten Klauseln."},{"text":"Ist eine Klausel unwirksam, bleibt der übrige Vertrag bestehen; statt der Klausel gilt das Gesetz.","is_correct":true,"rationale":"Das regelt § 306 BGB."},{"text":"AGB gelten gegenüber Verbrauchern automatisch, auch ohne Hinweis bei Vertragsschluss.","is_correct":false,"rationale":"Nötig sind ein ausdrücklicher Hinweis und die zumutbare Möglichkeit, sie zur Kenntnis zu nehmen (§ 305 Abs. 2 BGB)."},{"text":"Ein Händler kann gegenüber Verbrauchern die Gewährleistung für neue Waren per AGB vollständig ausschließen.","is_correct":false,"rationale":"Solche Klauseln sind unwirksam – die Gewährleistung beim Verbrauchsgüterkauf ist zwingend."}]}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
  kind = excluded.kind,
  scenario = excluded.scenario,
